#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: icebreaker × Keycloak 管理台接入
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"   # introduction/
CFG="$REPO_ROOT/config.yaml"
ENV_FILE="$REPO_ROOT/.keycloak-setup.env"                     # 只记非机密值
HOSTPORT="127.0.0.1:18080"                                    # 浏览器访问用
LISTEN=":18080"                                               # 服务监听用
REDIRECT_URI="http://$HOSTPORT/auth/callback"
BIN="/tmp/icebreaker-setup-bin"
PIDFILE="/tmp/icebreaker-setup.pid"
LOG="/tmp/icebreaker-setup.log"

# 预置默认值，让下面的 ask 都能"Enter 用当前值"（重跑也记得）。
write_env KC_ISSUER "$(_existing KC_ISSUER || echo https://login.bitnp.net/realms/master)" >/dev/null
write_env KC_CLIENT_ID "$(_existing KC_CLIENT_ID || echo icebreaker)" >/dev/null
write_env REDIRECT_URI "$(_existing REDIRECT_URI || echo "$REDIRECT_URI")" >/dev/null

# stop_server 按 pidfile 停（不用 pkill 模式匹配，免得误杀别的进程）。
stop_server() {
  [[ -f "$PIDFILE" ]] || return 0
  local pid; pid=$(cat "$PIDFILE" 2>/dev/null || true)
  if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then kill "$pid" 2>/dev/null || true; sleep 0.5; fi
  rm -f "$PIDFILE"
}

start_server() {
  stop_server
  # 直接后台起 nohup（nohup 会 exec 成目标进程），$! 就是它的 pid，kill 得掉。
  (
    cd "$REPO_ROOT"
    nohup "$BIN" -config "$CFG" > "$LOG" 2>&1 &
    echo $! > "$PIDFILE"
  )
  sleep 1.2
  if curl -sf -m 5 "http://$HOSTPORT/healthz" >/dev/null 2>&1; then
    printf '  %s✓%s 服务已起在 http://%s（日志 %s）\n' "$GREEN" "$RESET" "$HOSTPORT" "$LOG"
  else
    warn "服务没起来，看 $LOG"; tail -5 "$LOG" 2>/dev/null || true
  fi
}

# write_cfg 整份重写 config.yaml（旧文件先备份）。$1 是 admin_subs 的内容，可为空。
write_cfg() {
  local subs="$1" hmac
  [[ -f "$CFG" ]] && cp "$CFG" "$CFG.bak"
  hmac=$(openssl rand -base64 32 2>/dev/null | tr -d '\n' || head -c 32 /dev/urandom | base64 | tr -d '\n')
  cat > "$CFG" <<YAML
# 由 scripts/setup-keycloak.sh 生成。要手改就改这份；再跑向导会整份重写（先备份 .bak）。
server:
  addr: "$LISTEN"
db:
  path: "data/icebreaker.db"
auth:
  hmac_secret: "$hmac"
  token_ttl: 2h
  admin_subs: [$subs]
  oidc:
    issuer: "$KC_ISSUER"
    client_id: "$KC_CLIENT_ID"
    client_secret: "$KC_CLIENT_SECRET"
    redirect_url: "$REDIRECT_URI"
    display_name_claim: "name"
draw:
  themes: []
  shumeiniang_images: []
YAML
  printf '  %s✓%s 写好 %s\n' "$GREEN" "$RESET" "$CFG"
}

banner "icebreaker × Keycloak 管理台接入"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "确认能连上 Keycloak"
say "先确认这台机器拿得到 Keycloak 的 OIDC 配置。取不到，后面全是白搭。"
ask KC_ISSUER "Keycloak issuer（Enter 用默认）:"
code=$(curl -s -m 10 -o /tmp/kc-discovery.json -w '%{http_code}' \
  "$KC_ISSUER/.well-known/openid-configuration" || true)
if [[ "$code" != "200" ]]; then
  warn "拿不到 $KC_ISSUER/.well-known/openid-configuration（HTTP $code）"
  say "检查：本机网络/VPN/代理、issuer 拼写、realm 名。修好再重跑。"
  exit 1
fi
real_issuer=$(python3 -c "import json;print(json.load(open('/tmp/kc-discovery.json')).get('issuer',''))" 2>/dev/null || true)
if [[ -n "$real_issuer" && "$real_issuer" != "$KC_ISSUER" ]]; then
  warn "discovery 报的 issuer 是 $real_issuer，和你填的 $KC_ISSUER 不一致"
  say "两者必须一字不差，否则校验 id_token 的 issuer 会失败（少 /realms/xxx、多结尾斜杠、
走内部地址都会这样）。"
  pause "确认改用 discovery 里那个后按 Enter"
  KC_ISSUER="$real_issuer"
fi
write_env KC_ISSUER "$KC_ISSUER" >/dev/null
printf '  %s✓%s issuer: %s\n' "$GREEN" "$RESET" "$KC_ISSUER"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "在 Keycloak 里建 client"
say "这个 client 只给管理台登录用；签到和大屏不需要它。"
open_url "https://login.bitnp.net/admin/master/console/#/master/clients"
step "确认左上角 realm 是 master。"
step "Clients → Create client。"
step "General settings：Client ID 填 icebreaker（换名字也行，下一步照填）。"
step "Capability config：Client authentication = On，只勾 Standard flow，其余别勾，Save。"
step "Advanced/PKCE 那栏的 Code Challenge Method 留空：本服务是 confidential client + secret，不带 PKCE。"
step "Login settings：Valid redirect URIs 填 $REDIRECT_URI（一字不差），Save。"
note "以后上现场域名，回这一页把现场回调也加进 Valid redirect URIs（可以多条）。"
ask KC_CLIENT_ID "client id（Enter 用默认）:"
write_env KC_CLIENT_ID "$KC_CLIENT_ID" >/dev/null

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "复制 client secret"
step "还在这个 client 页面 → Credentials 标签页。"
step "Client secret 那一行，点复制。"
ask_secret KC_CLIENT_SECRET "粘贴 client secret（输入不回显）:"
if [[ -z "${KC_CLIENT_SECRET:-}" ]]; then
  warn "secret 不能为空。去 Credentials 页复制一次，重跑本向导。"
  exit 1
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "验证 client 并生成 config.yaml"
say "先拿 authorize 端点探一下：client 在不在、回调地址登记没登记。"
probe=$(curl -s -m 10 -G "https://login.bitnp.net/realms/master/protocol/openid-connect/auth" \
  --data-urlencode "client_id=$KC_CLIENT_ID" \
  --data-urlencode "redirect_uri=$REDIRECT_URI" \
  --data-urlencode "response_type=code" \
  --data-urlencode "scope=openid" \
  --data-urlencode "state=wizard" --data-urlencode "nonce=wizard" 2>/dev/null || true)
if grep -q "客户端未找到\|Client not found" <<<"$probe"; then
  warn "Keycloak 不认识 client「$KC_CLIENT_ID」：回 Stage 2 检查 Client ID 拼写和 realm 是否 master。"
  exit 1
elif grep -qi "redirect_uri" <<<"$probe"; then
  warn "回调地址没登记。把这个字符串一字不差加进 Login settings → Valid redirect URIs："
  say "    $REDIRECT_URI"
  exit 1
else
  printf '  %s✓%s client 与回调地址看起来都对\n' "$GREEN" "$RESET"
fi
write_cfg ""
say "config.yaml 里 admin_subs 现在是空的 —— 故意的：下一步登录会告诉我们填谁。"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "编译并启动服务，然后用你自己的浏览器登录"
say "编一个本地测试二进制（前端 build 过就会一起嵌进去）。"
( cd "$REPO_ROOT" && go build -o "$BIN" ./cmd/icebreaker )
printf '  %s✓%s 编译完成\n' "$GREEN" "$RESET"
start_server
say "下面这个地址用你自己的浏览器打开（要能输密码，别用无头浏览器）："
open_url "http://$HOSTPORT/#/admin"
step "用你的组织账号登录。"
step "登录成功会被弹回管理台；白名单此时是空的，页面会说「这个组织账号没有管理权限」。"
pause "登录完（看到那句没权限的提示）后按 Enter"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "把管理员 sub 写进白名单并重启"
found_sub=$(grep -o 'sub=[A-Za-z0-9._-]*' "$LOG" 2>/dev/null | tail -1 | cut -d= -f2 || true)
if [[ -n "$found_sub" ]]; then
  note "日志里抓到 sub=$found_sub"
  ADMIN_SUB="$found_sub"
else
  warn "日志里没抓到 sub。回浏览器看那句提示，把 sub= 后面那串复制过来。"
  ADMIN_SUB=""
fi
ask ADMIN_SUB "管理员 sub（Enter 用当前值 / 或粘贴）:"
if [[ -n "${ADMIN_SUB:-}" ]]; then
  write_env ADMIN_SUB "$ADMIN_SUB" >/dev/null
fi
write_cfg "${ADMIN_SUB:+\"$ADMIN_SUB\"}"
start_server
say "再打开一次，管理台应该完整可用了："
open_url "http://$HOSTPORT/#/admin"
note "停服务：kill \$(cat $PIDFILE)"

finish
